import { useState } from 'react';
import {
  JxField,
  JxInput,
  JxSelect,
  JxSwitch,
  JxButton,
} from '@jinx-ui/react';

type Language = 'ru' | 'en';

interface ProfileSettings {
  name: string;
  language: Language;
  emailNotifications: boolean;
}

interface ProfileSettingsFormProps {
  onSave: (settings: ProfileSettings) => void;
}

export default function ProfileSettingsForm({ onSave }: ProfileSettingsFormProps) {
  const [name, setName] = useState('');
  const [language, setLanguage] = useState<Language>('ru');
  const [emailNotifications, setEmailNotifications] = useState(false);

  const handleSubmit = (event: React.FormEvent<HTMLFormElement>) => {
    event.preventDefault();
    onSave({ name, language, emailNotifications });
  };

  return (
    <form
      className="jx-stack"
      style={{ gap: 'var(--jx-space-4)' }}
      onSubmit={handleSubmit}
    >
      <JxField label="Имя">
        <JxInput
          value={name}
          onValueChange={setName}
          placeholder="Введите имя"
        />
      </JxField>

      <JxField label="Язык интерфейса">
        <JxSelect value={language} onValueChange={(value) => setLanguage(value as Language)}>
          <JxSelect.Option value="ru">Русский</JxSelect.Option>
          <JxSelect.Option value="en">Английский</JxSelect.Option>
        </JxSelect>
      </JxField>

      <JxField label="Уведомления на почту">
        <JxSwitch
          checked={emailNotifications}
          onCheckedChange={setEmailNotifications}
        />
      </JxField>

      <JxButton type="submit" variant="primary">
        Сохранить
      </JxButton>
    </form>
  );
}

